// Full-document traversal: create small embedding batches, not one oversized request.
const CHUNK_CHARS=6000,OVERLAP_CHARS=500,EMBEDDING_BATCH_SIZE=8,MAX_CHUNKS_PER_DOCUMENT=48;
const output=[];
for(const item of $input.all()){
  const j=item.json,text=String(j.text||'');
  const chunks=[],weights=[];
  for(let i=0;i<text.length;i+=CHUNK_CHARS-OVERLAP_CHARS){
    const body=text.slice(i,i+CHUNK_CHARS);
    chunks.push(`Titel: ${j.detail.title||j.entityId}\nOrganisatie: ${j.detail.organization||j.sourceKey}\n\nInhoud:\n${body}`);
    weights.push(Math.max(1,body.length));
  }
  const totalChunks=Math.max(1,chunks.length);
  if(totalChunks>MAX_CHUNKS_PER_DOCUMENT){
    output.push({json:{outcome:'dead_letter',runId:j.runId,sourceKey:j.sourceKey,entityId:j.entityId,stage:'chunking',code:'document_chunk_budget_exceeded',message:`Document requires ${totalChunks} chunks; maximum is ${MAX_CHUNKS_PER_DOCUMENT}`,document_characters:text.length,required_chunks:totalChunks,max_chunks:MAX_CHUNKS_PER_DOCUMENT}});
    continue;
  }
  for(let offset=0;offset<chunks.length;offset+=EMBEDDING_BATCH_SIZE){
    output.push({json:{...j,text:undefined,chunks:chunks.slice(offset,offset+EMBEDDING_BATCH_SIZE),chunk_weights:weights.slice(offset,offset+EMBEDDING_BATCH_SIZE),document_characters:text.length,chunk_count:totalChunks,embedding_batch_index:offset/EMBEDDING_BATCH_SIZE,embedding_batch_count:Math.ceil(totalChunks/EMBEDDING_BATCH_SIZE),text_truncated:false}});
  }
}
return output;

// Combine all bounded embedding requests for each document with a weighted mean.
const results=$input.all(), originals=$('7. Bound Text And Build Chunks').all();
function pointId(input){let h1=0xdeadbeef,h2=0x41c64e6d,h3=0x12345678,h4=0x87654321;for(const c of input){const x=c.charCodeAt(0);h1=Math.imul(h1^x,2654435761);h2=Math.imul(h2^x,1597334677);h3=Math.imul(h3^x,2246822507);h4=Math.imul(h4^x,3266489909)}const hex=[h1,h2,h3,h4].map(x=>(x>>>0).toString(16).padStart(8,'0')).join('');return `${hex.slice(0,8)}-${hex.slice(8,12)}-5${hex.slice(13,16)}-${((parseInt(hex.slice(16,18),16)&0x3f)|0x80).toString(16)}${hex.slice(18,20)}-${hex.slice(20,32)}`;}
const groups=new Map();
for(let index=0;index<results.length;index++){
  const original=originals[index]?.json, result=results[index];
  if(!original) continue;
  const group=groups.get(original.entityId)||{original,batches:[],error:null};
  if(result.error||result.json?.error) group.error=String((result.error||result.json?.error).message||'Embedding request failed').slice(0,500);
  else group.batches.push({data:result.json.data||[],weights:original.chunk_weights||[]});
  groups.set(original.entityId,group);
}
const output=[];
for(const [entityId,group] of groups){
  const o=group.original||{};
  if(!o.detail){output.push({json:{outcome:'dead_letter',runId:o.runId||null,sourceKey:o.sourceKey||null,entityId,stage:'entity_detail',code:'missing_indexable_detail',message:'No entity detail/text was available for embedding'}});continue;}
  if(group.error){output.push({json:{outcome:'dead_letter',runId:o.runId||null,sourceKey:o.sourceKey||null,entityId,stage:'embedding',code:'http_failure',message:group.error}});continue;}
  const vectors=[],weights=[];
  for(const batch of group.batches) for(let i=0;i<batch.data.length;i++){const vector=batch.data[i]?.embedding;if(Array.isArray(vector)) {vectors.push(vector);weights.push(Number(batch.weights[i]||1));}}
  if(!vectors.length||vectors[0].length!==3072){output.push({json:{outcome:'dead_letter',runId:o.runId||null,sourceKey:o.sourceKey||null,entityId,stage:'embedding',code:'invalid_vector',message:'Embedding output missing or unexpected dimension'}});continue;}
  const averaged=new Array(3072).fill(0); let weightTotal=0;
  for(let i=0;i<vectors.length;i++){const weight=weights[i];weightTotal+=weight;for(let d=0;d<3072;d++)averaged[d]+=vectors[i][d]*weight;}
  for(let d=0;d<3072;d++)averaged[d]/=weightTotal;
  const norm=Math.sqrt(averaged.reduce((sum,value)=>sum+value*value,0)); const vector=norm?averaged.map(value=>value/norm):averaged;
  const d=o.detail||{},r=o.record||{};
  output.push({json:{outcome:'continue',collection:o.collection||'openbesluitvorming',point:{id:pointId(entityId),vector,payload:{source_id:entityId,source_key:o.sourceKey,entity_type:'Document',supplier:r?.supplier||null,commit_id:r?.commit_id||null,content_hash:r?.content_hash||null,source_sequence:r?.seq??null,source_operation:r?.op||null,source_time:r?.time||null,schema_version:r?.schema_version||null,title:d?.title||entityId,organization:d?.organization||null,date:d?.sortDate||d?.date||null,meeting_id:d?.meetingId||null,download_url:d?.downloadUrl||null,pdf_url:d?.pdfUrl||null,original_url:r?.payload?.original_url||null,file_name:r?.payload?.file_name||null,classification:r?.payload?.classification||[],last_discussed_at:r?.payload?.last_discussed_at||null,referenced_by:r?.payload?.is_referenced_by||null,derived_content:r?.payload?.derived_content||{},media_urls:r?.payload?.media_urls||[],source_payload:r?.payload||{},content_preview:String(d?.markdownText||d?.markdown_text||'').slice(0,3000),text_truncated:false,document_characters:o.document_characters,chunk_count:o.chunk_count,embedding_batch_count:o.embedding_batch_count,indexed_at:new Date().toISOString()}},runId:o.runId||null,sourceKey:o.sourceKey||null,entityId}});
}
return output;

const results=$input.all(), originals=$('9. Mean Pool And Build Point').all();
const output=[];
for(let index=0;index<results.length;index++){
  const result=results[index],p=originals[index]?.json;
  if(!p){output.push({json:{outcome:'dead_letter',stage:'qdrant_upsert',code:'input_alignment_failed',message:'Could not align Qdrant response to source point'}});continue;}
  if(result.error||result.json?.error){output.push({json:{outcome:'dead_letter',runId:p.runId||null,sourceKey:p.sourceKey||null,entityId:p.entityId||null,stage:'qdrant_upsert',code:'http_failure',message:String((result.error||result.json?.error).message||'Qdrant upsert failed').slice(0,500)}});continue;}
  output.push({json:{outcome:'indexed',runId:p.runId||null,sourceKey:p.sourceKey||null,entityId:p.entityId||null,truncated:Boolean(p.point?.payload?.text_truncated),stage:'qdrant_upsert'}});
}
return output;
